    Rgb10x2Le = 141,
}

/// <summary>The different video flags that a format info can have.</summary>
[Flags]
public enum VideoFormatFlags
{
    /// <summary>
    /// The video format is YUV, components are numbered
    ///   0=Y, 1=U, 2=V.
    /// </summary>
    Yuv = 0x00000001,

    /// <summary>
    /// The video format is RGB, components are numbered
    ///   0=R, 1=G, 2=B.
    /// </summary>
    Rgb = 0x00000002,

    /// <summary>
    /// The video is gray, there is one gray component
    ///   with index 0.
    /// </summary>
    Gray = 0x00000004,

    /// <summary>
    /// The video format has an alpha components with
    ///   the number 3.
    /// </summary>
    Alpha = 0x00000008,

    /// <summary>
    /// The video format has data stored in little
    ///   endianness.
    /// </summary>
    Le = 0x00000010,

    /// <summary>
    /// The video format has a palette. The palette
    ///   is stored in the second plane and indexes are stored in the first plane.
    /// </summary>
    Palette = 0x00000020,

    /// <summary>
    /// The video format has a complex layout that
    ///   can't be described with the usual information in the #GstVideoFormatInfo.
    /// </summary>
    Complex = 0x00000040,

    /// <summary>
    /// This format can be used in a
    ///   #GstVideoFormatUnpack and #GstVideoFormatPack function.
    /// </summary>
    Unpack = 0x00000080,

    /// <summary>
    /// The format is tiled, there is tiling information
    ///   in the last plane.
    /// </summary>
    Tiled = 0x00000100,

    /// <summary>The tile size varies per plane according to the subsampling.</summary>
    Subtiles = 0x00000200,
}

/// <summary>Extra video frame flags</summary>
[Flags]
public enum VideoFrameFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>
    /// The video frame is interlaced. In mixed
    ///           interlace-mode, this flag specifies if the frame is interlaced or
    ///           progressive.
    /// </summary>
    Interlaced = 0x00000001,

    /// <summary>The video frame has the top field first</summary>
    Tff = 0x00000002,

    /// <summary>The video frame has the repeat flag</summary>
    Rff = 0x00000004,

    /// <summary>The video frame has one field</summary>
    Onefield = 0x00000008,

    /// <summary>
    /// The video contains one or
    ///     more non-mono views
    /// </summary>
    MultipleView = 0x00000010,

    /// <summary>
    /// The video frame is the first
    ///     in a set of corresponding views provided as sequential frames.
    /// </summary>
    FirstInBundle = 0x00000020,

    /// <summary>
    /// The video frame has the top field only. This
    ///     is the same as GST_VIDEO_FRAME_FLAG_TFF | GST_VIDEO_FRAME_FLAG_ONEFIELD
    ///     (Since: 1.16).
    /// </summary>
    TopField = 0x0000000A,

    /// <summary>
    /// The video frame has the bottom field
    ///     only. This is the same as GST_VIDEO_FRAME_FLAG_ONEFIELD
    ///     (GST_VIDEO_FRAME_FLAG_TFF flag unset) (Since: 1.16).
    /// </summary>
    BottomField = 0x00000008,
}

/// <summary>Additional mapping flags for gst_video_frame_map().</summary>
[Flags]
public enum VideoFrameMapFlags
{
    /// <summary>
    /// Don't take another reference of the buffer and store it in
