    ///                                    buffer reference stays valid until the frame is unmapped again.
    /// </summary>
    NoRef = 0x00010000,

    /// <summary>Offset to define more flags</summary>
    Last = 0x01000000,
}

/// <summary>The orientation of the GL texture.</summary>
public enum VideoGLTextureOrientation
{
    /// <summary>Top line first in memory, left row first</summary>
    NormalYNormal = 0,

    /// <summary>Bottom line first in memory, left row first</summary>
    NormalYFlip = 1,

    /// <summary>Top line first in memory, right row first</summary>
    FlipYNormal = 2,

    /// <summary>Bottom line first in memory, right row first</summary>
    FlipYFlip = 3,
}

/// <summary>The GL texture type.</summary>
public enum VideoGLTextureType
{
    /// <summary>Luminance texture, GL_LUMINANCE</summary>
    Luminance = 0,

    /// <summary>Luminance-alpha texture, GL_LUMINANCE_ALPHA</summary>
    LuminanceAlpha = 1,

    /// <summary>RGB 565 texture, GL_RGB</summary>
    Rgb16 = 2,

    /// <summary>RGB texture, GL_RGB</summary>
    Rgb = 3,

    /// <summary>RGBA texture, GL_RGBA</summary>
    Rgba = 4,

    /// <summary>R texture, GL_RED_EXT</summary>
    R = 5,

    /// <summary>RG texture, GL_RG_EXT</summary>
    Rg = 6,
}

/// <summary>The <c>GstVideoGammaMode</c> enumeration.</summary>
public enum VideoGammaMode
{
    /// <summary>disable gamma handling</summary>
    None = 0,

    /// <summary>
    /// convert between input and output gamma
    /// Different gamma conversion modes
    /// </summary>
    Remap = 1,
}

/// <summary>
/// The possible values of the #GstVideoInterlaceMode describing the interlace
/// mode of the stream.
/// </summary>
public enum VideoInterlaceMode
{
    /// <summary>all frames are progressive</summary>
    Progressive = 0,

    /// <summary>
    /// 2 fields are interleaved in one video
    ///     frame. Extra buffer flags describe the field order.
    /// </summary>
    Interleaved = 1,

    /// <summary>
    /// frames contains both interlaced and
    ///     progressive video, the buffer flags describe the frame and fields.
    /// </summary>
    Mixed = 2,

    /// <summary>
    /// 2 fields are stored in one buffer, use the
    ///     frame ID to get access to the required field. For multiview (the
    ///     'views' property &gt; 1) the fields of view N can be found at frame ID
    ///     (N * 2) and (N * 2) + 1.
    ///     Each field has only half the amount of lines as noted in the
    ///     height property. This mode requires multiple GstVideoMeta metadata
    ///     to describe the fields.
    /// </summary>
    Fields = 3,

    /// <summary>
    /// 1 field is stored in one buffer,
    ///     @GST_VIDEO_BUFFER_FLAG_TF or @GST_VIDEO_BUFFER_FLAG_BF indicates if
    ///     the buffer is carrying the top or bottom field, respectively. The top and
    ///     bottom buffers must alternate in the pipeline, with this mode
    ///     (Since: 1.16).
    /// </summary>
    Alternate = 4,
}

/// <summary>Different color matrix conversion modes</summary>
public enum VideoMatrixMode
{
    /// <summary>do conversion between color matrices</summary>
    Full = 0,

    /// <summary>
    /// use the input color matrix to convert
    ///   to and from R'G'B
    /// </summary>
    InputOnly = 1,

    /// <summary>
    /// use the output color matrix to convert
    ///   to and from R'G'B
    /// </summary>
    OutputOnly = 2,

    /// <summary>disable color matrix conversion.</summary>
    None = 3,
}

/// <summary>
/// GstVideoMultiviewFlags are used to indicate extra properties of a
/// stereo/multiview stream beyond the frame layout and buffer mapping
/// that is conveyed in the #GstVideoMultiviewMode.
/// </summary>
[Flags]
public enum VideoMultiviewFlags
{
    /// <summary>No flags</summary>
    None = 0x00000000,

    /// <summary>
    /// For stereo streams, the
    ///     normal arrangement of left and right views is reversed.
    /// </summary>
    RightViewFirst = 0x00000001,

    /// <summary>
    /// The left view is vertically
    ///     mirrored.
    /// </summary>
    LeftFlipped = 0x00000002,

    /// <summary>
    /// The left view is horizontally
    ///     mirrored.
    /// </summary>
    LeftFlopped = 0x00000004,

    /// <summary>
    /// The right view is
    ///     vertically mirrored.
    /// </summary>
    RightFlipped = 0x00000008,

    /// <summary>
    /// The right view is
    ///     horizontally mirrored.
    /// </summary>
    RightFlopped = 0x00000010,

    /// <summary>
    /// For frame-packed
    ///     multiview modes, indicates that the individual
    ///     views have been encoded with half the true width or height
    ///     and should be scaled back up for display. This flag
    ///     is used for overriding input layout interpretation
    ///     by adjusting pixel-aspect-ratio.
    ///     For side-by-side, column interleaved or checkerboard packings, the
    ///     pixel width will be doubled. For row interleaved and top-bottom
    ///     encodings, pixel height will be doubled.
    /// </summary>
    HalfAspect = 0x00004000,

    /// <summary>
    /// The video stream contains both
    ///     mono and multiview portions, signalled on each buffer by the
    ///     absence or presence of the @GST_VIDEO_BUFFER_FLAG_MULTIPLE_VIEW
    ///     buffer flag.
    /// </summary>
    MixedMono = 0x00008000,
}

/// <summary>
/// #GstVideoMultiviewFramePacking represents the subset of #GstVideoMultiviewMode
/// values that can be applied to any video frame without needing extra metadata.
/// It can be used by elements that provide a property to override the
/// multiview interpretation of a video stream when the video doesn't contain
/// any markers.
/// </summary>
/// <remarks>
/// <para>
/// This enum is used (for example) on playbin, to re-interpret a played
/// video stream as a stereoscopic video. The individual enum values are
/// equivalent to and have the same value as the matching #GstVideoMultiviewMode.
/// </para>
/// </remarks>
public enum VideoMultiviewFramePacking
{
    /// <summary>
    /// A special value indicating
    /// no frame packing info.
    /// </summary>
    None = -1,

    /// <summary>All frames are monoscopic.</summary>
    Mono = 0,

    /// <summary>All frames represent a left-eye view.</summary>
    Left = 1,

    /// <summary>All frames represent a right-eye view.</summary>
    Right = 2,

    /// <summary>
    /// Left and right eye views are
    /// provided in the left and right half of the frame respectively.
    /// </summary>
    SideBySide = 3,

    /// <summary>
    /// Left and right eye
    /// views are provided in the left and right half of the frame, but
    /// have been sampled using quincunx method, with half-pixel offset
    /// between the 2 views.
    /// </summary>
    SideBySideQuincunx = 4,

    /// <summary>
    /// Alternating vertical
    /// columns of pixels represent the left and right eye view respectively.
    /// </summary>
    ColumnInterleaved = 5,

    /// <summary>
    /// Alternating horizontal
    /// rows of pixels represent the left and right eye view respectively.
    /// </summary>
    RowInterleaved = 6,

    /// <summary>
    /// The top half of the frame
    /// contains the left eye, and the bottom half the right eye.
    /// </summary>
    TopBottom = 7,

    /// <summary>
    /// Pixels are arranged with
    /// alternating pixels representing left and right eye views in a
    /// checkerboard fashion.
    /// </summary>
    Checkerboard = 8,
}

/// <summary>
/// All possible stereoscopic 3D and multiview representations.
/// In conjunction with #GstVideoMultiviewFlags, describes how
/// multiview content is being transported in the stream.
/// </summary>
public enum VideoMultiviewMode
{
    /// <summary>
    /// A special value indicating
    /// no multiview information. Used in GstVideoInfo and other places to
    /// indicate that no specific multiview handling has been requested or
    /// provided. This value is never carried on caps.
    /// </summary>
    None = -1,

    /// <summary>All frames are monoscopic.</summary>
    Mono = 0,

    /// <summary>All frames represent a left-eye view.</summary>
    Left = 1,

    /// <summary>All frames represent a right-eye view.</summary>
    Right = 2,

    /// <summary>
    /// Left and right eye views are
    /// provided in the left and right half of the frame respectively.
    /// </summary>
    SideBySide = 3,

    /// <summary>
    /// Left and right eye
    /// views are provided in the left and right half of the frame, but
    /// have been sampled using quincunx method, with half-pixel offset
    /// between the 2 views.
    /// </summary>
    SideBySideQuincunx = 4,

    /// <summary>
    /// Alternating vertical
    /// columns of pixels represent the left and right eye view respectively.
    /// </summary>
    ColumnInterleaved = 5,

    /// <summary>
    /// Alternating horizontal
    /// rows of pixels represent the left and right eye view respectively.
    /// </summary>
    RowInterleaved = 6,

    /// <summary>
    /// The top half of the frame
    /// contains the left eye, and the bottom half the right eye.
    /// </summary>
    TopBottom = 7,

    /// <summary>
    /// Pixels are arranged with
    /// alternating pixels representing left and right eye views in a
    /// checkerboard fashion.
    /// </summary>
    Checkerboard = 8,

    /// <summary>
    /// Left and right eye views
    /// are provided in separate frames alternately.
    /// </summary>
    FrameByFrame = 32,

    /// <summary>
    /// Multiple
    /// independent views are provided in separate frames in sequence.
    /// This method only applies to raw video buffers at the moment.
    /// Specific view identification is via the `GstVideoMultiviewMeta`
    /// and #GstVideoMeta(s) on raw video buffers.
    /// </summary>
    MultiviewFrameByFrame = 33,

    /// <summary>
    /// Multiple views are
    /// provided as separate #GstMemory framebuffers attached to each
    /// #GstBuffer, described by the `GstVideoMultiviewMeta`
    /// and #GstVideoMeta(s)
    /// </summary>
    Separated = 34,
}

/// <summary>The different video orientation methods.</summary>
public enum VideoOrientationMethod
{
    /// <summary>Identity (no rotation)</summary>
    Identity = 0,

    /// <summary>Rotate clockwise 90 degrees</summary>
    _90r = 1,

    /// <summary>Rotate 180 degrees</summary>
    _180 = 2,

    /// <summary>Rotate counter-clockwise 90 degrees</summary>
    _90l = 3,

    /// <summary>Flip horizontally</summary>
    Horiz = 4,

    /// <summary>Flip vertically</summary>
    Vert = 5,

    /// <summary>Rotate counter-clockwise 90 degrees and flip vertically</summary>
    UlLr = 6,

    /// <summary>Rotate clockwise 90 degrees and flip vertically</summary>
    UrLl = 7,

    /// <summary>Select flip method based on image-orientation tag</summary>
    Auto = 8,

    /// <summary>Current status depends on plugin internal setup</summary>
    Custom = 9,
}

/// <summary>Overlay format flags.</summary>
[Flags]
public enum VideoOverlayFormatFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>RGB are premultiplied by A/255.</summary>
    PremultipliedAlpha = 0x00000001,

    /// <summary>a global-alpha value != 1 is set.</summary>
    GlobalAlpha = 0x00000002,
}

/// <summary>The different flags that can be used when packing and unpacking.</summary>
[Flags]
public enum VideoPackFlags
{
    /// <summary>No flag</summary>
    None = 0x00000000,

    /// <summary>
    /// When the source has a smaller depth
    ///   than the target format, set the least significant bits of the target
    ///   to 0. This is likely slightly faster but less accurate. When this flag
    ///   is not specified, the most significant bits of the source are duplicated
    ///   in the least significant bits of the destination.
    /// </summary>
    TruncateRange = 0x00000001,

    /// <summary>
    /// The source is interlaced. The unpacked
    ///   format will be interlaced as well with each line containing
    ///   information from alternating fields. (Since: 1.2)
    /// </summary>
    Interlaced = 0x00000002,
}

/// <summary>Different primaries conversion modes</summary>
public enum VideoPrimariesMode
{
    /// <summary>disable conversion between primaries</summary>
    None = 0,

    /// <summary>
    /// do conversion between primaries only
    ///   when it can be merged with color matrix conversion.
    /// </summary>
    MergeOnly = 1,

    /// <summary>fast conversion between primaries</summary>
    Fast = 2,
}

/// <summary>Different resampler flags.</summary>
[Flags]
public enum VideoResamplerFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>
    /// when no taps are given, half the
    ///              number of calculated taps. This can be used when making scalers
    ///              for the different fields of an interlaced picture. Since: 1.10
    /// </summary>
    HalfTaps = 0x00000001,
}

/// <summary>Different subsampling and upsampling methods</summary>
public enum VideoResamplerMethod
{
    /// <summary>
    /// Duplicates the samples when
    ///    upsampling and drops when downsampling
    /// </summary>
    Nearest = 0,

    /// <summary>
    /// Uses linear interpolation to reconstruct
    ///    missing samples and averaging to downsample
    /// </summary>
    Linear = 1,

    /// <summary>Uses cubic interpolation</summary>
    Cubic = 2,

    /// <summary>Uses sinc interpolation</summary>
    Sinc = 3,

    /// <summary>Uses lanczos interpolation</summary>
    Lanczos = 4,
}

/// <summary>Different scale flags.</summary>
[Flags]
public enum VideoScalerFlags
{
    /// <summary>no flags</summary>
    None = 0x00000000,

    /// <summary>Set up a scaler for interlaced content</summary>
    Interlaced = 0x00000001,
}

/// <summary>Enum value describing the available tiling modes.</summary>
public enum VideoTileMode
{
    /// <summary>Unknown or unset tile mode</summary>
    Unknown = 0,

    /// <summary>
    /// Every four adjacent blocks - two
    ///    horizontally and two vertically are grouped together and are located
    ///    in memory in Z or flipped Z order. In case of odd rows, the last row
    ///    of blocks is arranged in linear order.
    /// </summary>
    Zflipz2x2 = 65536,

    /// <summary>Tiles are in row order.</summary>
    Linear = 131072,
}

/// <summary>Enum value describing the most common tiling types.</summary>
