    Indexed = 0,
}

/// <summary>
/// Flags related to the time code information.
/// For drop frame, only 30000/1001 and 60000/1001 frame rates are supported.
/// </summary>
[Flags]
public enum VideoTimeCodeFlags
{
    /// <summary>No flags</summary>
    None = 0x00000000,

    /// <summary>Whether we have drop frame rate</summary>
    DropFrame = 0x00000001,

    /// <summary>Whether we have interlaced video</summary>
    Interlaced = 0x00000002,
}

/// <summary>
/// The video transfer function defines the formula for converting between
/// non-linear RGB (R'G'B') and linear RGB
/// </summary>
public enum VideoTransferFunction
{
    /// <summary>unknown transfer function</summary>
    Unknown = 0,

    /// <summary>linear RGB, gamma 1.0 curve</summary>
    Gamma10 = 1,

    /// <summary>Gamma 1.8 curve</summary>
    Gamma18 = 2,

    /// <summary>Gamma 2.0 curve</summary>
    Gamma20 = 3,

    /// <summary>Gamma 2.2 curve</summary>
    Gamma22 = 4,

    /// <summary>
    /// Gamma 2.2 curve with a linear segment in the lower
    ///                           range, also ITU-R BT470M / ITU-R BT1700 625 PAL &amp;
    ///                           SECAM / ITU-R BT1361
    /// </summary>
    Bt709 = 5,

    /// <summary>
    /// Gamma 2.2 curve with a linear segment in the
    ///                               lower range
    /// </summary>
    Smpte240m = 6,

    /// <summary>
    /// Gamma 2.4 curve with a linear segment in the lower
    ///                          range. IEC 61966-2-1 (sRGB or sYCC)
    /// </summary>
    Srgb = 7,

    /// <summary>Gamma 2.8 curve, also ITU-R BT470BG</summary>
    Gamma28 = 8,

    /// <summary>
    /// Logarithmic transfer characteristic
    ///                             100:1 range
    /// </summary>
    Log100 = 9,

    /// <summary>
    /// Logarithmic transfer characteristic
    ///                             316.22777:1 range (100 * sqrt(10) : 1)
    /// </summary>
    Log316 = 10,

    /// <summary>
    /// Gamma 2.2 curve with a linear segment in the lower
    ///                                range. Used for BT.2020 with 12 bits per
    ///                                component. Since: 1.6
    /// </summary>
    Bt202012 = 11,

    /// <summary>Gamma 2.19921875. Since: 1.8</summary>
    Adobergb = 12,

    /// <summary>
    /// Rec. ITU-R BT.2020-2 with 10 bits per component.
    ///                                (functionally the same as the values
    ///                                GST_VIDEO_TRANSFER_BT709 and GST_VIDEO_TRANSFER_BT601).
    ///                                Since: 1.18
    /// </summary>
    Bt202010 = 13,

    /// <summary>
    /// SMPTE ST 2084 for 10, 12, 14, and 16-bit systems.
    ///                                Known as perceptual quantization (PQ)
    ///                                Since: 1.18
    /// </summary>
    Smpte2084 = 14,

    /// <summary>
    /// Association of Radio Industries and Businesses (ARIB)
    ///                                   STD-B67 and Rec. ITU-R BT.2100-1 hybrid loggamma (HLG) system
    ///                                   Since: 1.18
    /// </summary>
    AribStdB67 = 15,

    /// <summary>also known as SMPTE170M / ITU-R BT1358 525 or 625 / ITU-R BT1700 NTSC</summary>
    Bt601 = 16,
}

